            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "To all who come to this happy place: Welcome. Disneyland is your land. Here age relives fond memories of the past, and here youth may savor the challenge and promise of the future.", Author = "Walt Disney" },
